import{_ as e,o,c as a,U as r}from"./chunks/framework.CYN6H5OD.js";const h=JSON.parse('{"title":"Introduction","description":"","frontmatter":{"outline":[2,3]},"headers":[],"relativePath":"about.md","filePath":"about.md"}'),n={name:"about.md"};function i(s,t,l,d,u,c){return o(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><div class="lead"><p><strong>Vue MDBootstrap</strong> is a collection of Vue.js UI components and was built from the ground up to be easy to learn and use. Our collection of UI components maintain a consistent style throughout your application with enough customization options to meet any use-case.</p></div><h2 id="why-vue-mdbootstrap" tabindex="-1">Why Vue MDBootstrap? <a class="header-anchor" href="#why-vue-mdbootstrap" aria-label="Permalink to &quot;Why Vue MDBootstrap?&quot;">​</a></h2><p><strong>Vue MDBootstrap</strong> is an attempt to have Vue3 components with Typescript. At first we just support <strong>Bootstrap v5</strong>. Later we saw <strong>TailwindCSS</strong> also becomes more popular and widely used. And now, <strong>Vue MDBootstrap</strong> also comes with support for <strong>TailwindCSS v4</strong>. Another goal is to have the components written in a simple and readable way for a better developer experience.</p><h3 id="flexible-components" tabindex="-1">Flexible components <a class="header-anchor" href="#flexible-components" aria-label="Permalink to &quot;Flexible components&quot;">​</a></h3><p>Every component in <strong>Vue MDBootstrap</strong> is built according to the <a href="https://m3.material.io/" target="_blank" rel="noreferrer">Google Material Design 3</a> specifications and comes with many customization options suitable for most style or design; even though it’s not Material Design. Our UI components can leverage the world&#39;s most popular css framework - <em>Bootstrap v5</em> and <em>TailwindCSS v4</em>, which can help you build responsive apps faster and mobile friendly.</p><h3 id="it-s-free" tabindex="-1">It’s free <a class="header-anchor" href="#it-s-free" aria-label="Permalink to &quot;It’s free&quot;">​</a></h3><p><strong>Vue MDBootstrap</strong> is an Open Source project available for free under the BSD-3-Clause license. Additionally, the source code is available on <a href="https://github.com/ahmadfajar/vue-mdbootstrap" target="_blank" rel="noreferrer">GitHub</a>, allowing developers to modify and contribute to its development if they choose to do so.</p><h2 id="documentation-sections" tabindex="-1">Documentation Sections <a class="header-anchor" href="#documentation-sections" aria-label="Permalink to &quot;Documentation Sections&quot;">​</a></h2><p>The online documentation consists of the following sections:</p><ul><li><a href="/getting-started/installation">Getting Started</a> - Documentation on how to install and using the components</li><li><a href="/components/">Components</a> - Visual component library documentation</li><li><a href="/reference/">Reference</a> - Additional resources documentation</li></ul><h2 id="additional-information" tabindex="-1">Additional Information <a class="header-anchor" href="#additional-information" aria-label="Permalink to &quot;Additional Information&quot;">​</a></h2><p>Before getting started with <strong>Vue MDBootstrap</strong>, you should have general familiarity with <strong>Vue 3</strong> functionality, Bootstrap v5 and/or TailwindCSS. If you are unfamiliar with Vue.js and/or Bootstrap, some good starting points would be:</p><ul><li><a href="https://vuejs.org/guide/" target="_blank" rel="noreferrer">Vue Guide</a></li><li><a href="https://vuejs.org/api/" target="_blank" rel="noreferrer">Vue API</a></li><li><a href="https://getbootstrap.com/docs/5.3/getting-started/introduction/" target="_blank" rel="noreferrer">Bootstrap documentation</a></li><li><a href="https://tailwindcss.com/docs" target="_blank" rel="noreferrer">TailwindCSS documentation</a></li></ul><h2 id="browser-support" tabindex="-1">Browser Support <a class="header-anchor" href="#browser-support" aria-label="Permalink to &quot;Browser Support&quot;">​</a></h2><p>All major modern browsers.</p>',16)])])}const m=e(n,[["render",i]]);export{h as __pageData,m as default};
